const item = $input.item.json;
const step = Number(item.step) || 0;
const nextStep = step + 1;
const emailType = nextStep === 1 ? 'initial' : ('followup_' + (nextStep - 1));
const isWebsite = item.sequence_type === 'website_demo';
const bizName = item.business_name || 'there';
const demoLine = item.demo_url ? ('Take a look here: ' + item.demo_url) : '';
const productLabel = isWebsite ? 'a free mockup of what your website could look like' : 'a live demo of an AI chatbot for your website';

let subject = '';
let html = '';

if (nextStep === 1) {
  subject = isWebsite ? ('A free website mockup for ' + bizName) : ('A quick chatbot demo for ' + bizName);
  html = '<p>Hi ' + bizName + ',</p>' +
    '<p>I put together ' + productLabel + '. ' + demoLine + '</p>' +
    '<p>No obligation, just wanted to show you what is possible. Happy to answer any questions.</p>' +
    '<p>Best,<br>Nabeel</p>';
} else {
  subject = 'Following up - ' + bizName;
  html = '<p>Hi ' + bizName + ',</p>' +
    '<p>Just following up on the ' + (isWebsite ? 'website mockup' : 'chatbot demo') + ' I sent over. ' + demoLine + '</p>' +
    '<p>Let me know if you would like to move forward or have any questions.</p>' +
    '<p>Best,<br>Nabeel</p>';
}

const newStatus = nextStep >= 5 ? 'completed_no_reply' : 'active';

return {
  json: {
    sequence_id: item.sequence_id,
    tenant_id: item.tenant_id,
    lead_id: item.lead_id,
    email: item.email,
    business_name: bizName,
    next_step: nextStep,
    email_type: emailType,
    subject: subject,
    html: html,
    new_status: newStatus
  }
};
